"""Full-root original/candidate comparison with separate bounded verification."""
import hashlib,json,sys,time
from pathlib import Path
source, case_json, mode, output = sys.argv[1:]
sys.path.insert(0,source)
from bj import ev,joint_ace_resplit,_enumeration
from bj.bounded_ace_resplit import decide,rank
from bj.common_shoe import reference_counts
from bj.core import Rules
case=json.loads(case_json)
rules=Rules(max_hands=3,resplit_aces=True,hit_split_aces=False,s17=case['s17'],das=case['das'])
class VerificationBudget:
 def __init__(self): self.counts={};self.attempted=0
 def enter(self,family):
  self.attempted+=1
  if self.attempted>500000: raise RuntimeError('separate original-arithmetic verification cap exceeded')
  self.counts[family]=self.counts.get(family,0)+1
 def snapshot(self):
  return {'verification_only':True,'limit':500000,'states':sum(self.counts.values()),'attempted_states':self.attempted,'state_counts':dict(sorted(self.counts.items()))}
def verification_limit(value):
 if type(value) is not int or value!=500000: raise ValueError('private verifier admits exactly the frozen500000 limit')
 return value
token=None
start=time.perf_counter()
try:
 if mode=='original-verification':
  budget=VerificationBudget();token=_enumeration._active.set(budget)
  joint_ace_resplit.state_limit=verification_limit
  _,values,_=ev.best_action(('A','A'),case['up'],shoe=tuple(case['counts']),rules=rules,can_double=True,can_split=False)
  split=joint_ace_resplit.joint_ace_resplit_value(case['up'],reference_counts(case['counts']),
       double_after_split=rules.das,stand_soft_17=rules.s17,max_states=500000)
  values['P']=split.value;action,margin=rank(values);work=budget.snapshot()
 else:
  action,values,margin,work=decide(('A','A'),case['up'],tuple(case['counts']),rules,max_states=100000)
 result={'status':'complete','action':action,'values_hex':{k:v.hex() for k,v in values.items()},'margin_hex':margin.hex(),'work':work}
except Exception as exc:
 result={'status':'refused','type':type(exc).__name__,'reason':str(exc),'work':getattr(exc,'work',None)}
 if mode=='original-verification':result['verification_work']=budget.snapshot()
finally:
 if token is not None:_enumeration._active.reset(token)
result.update(case=case,mode=mode,elapsed_call_seconds=time.perf_counter()-start,
 product_limit_unchanged=_enumeration.MAX_STATES==100000,verification_bound_only=mode=='original-verification')
result['source_sha256']={name:hashlib.sha256(Path(source,name).read_text(encoding='utf-8-sig').replace('\r\n','\n').encode()).hexdigest()
 for name in ('bj/joint_ace_resplit.py','bj/bounded_ace_resplit.py','bj/ev.py','bj/_enumeration.py')}
with Path(output).open('x',encoding='utf-8') as stream:json.dump(result,stream,indent=2,allow_nan=False);stream.write('\n')
print(json.dumps({k:v for k,v in result.items() if k not in ('case','source_sha256')}))

